Given a sorted doubly linked list of positive distinct elements, the task is to find pairs in a doubly-linked list whose sum is equal to the given value x in sorted order. Examples:Input: Output: (1, 6), (2,5)Explanation: We can see that there are two pairs (1, 6) and (2, 5) with sum 7.Input:  Output: (1,5)Explanation: We can see that there is one pair (1, 5) with a sum of 6.Try It YourselfTable of Content[Naive Approach] Using Hashing - O(nlogn) Time and O(n) Space[Expected Approach] Using Two Pointer Technique - O(n) Time and O(1) Space[Naive Approach] Using Hashing - O(nlogn) Time and O(n) SpaceThis approach finds pairs of nodes in a doubly linked list that sum up to a given target. It uses a hash map to track the values of nodes as the list is traversed. For each node, it calculates the complement (target - node value) and checks if it exists in the map. If found, a valid pair is stored. After traversal, the pairs are sorted to maintain the order.
            C++

    // C++ program to find a pair with given sum x
// using map
#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    int data;
    Node *next;
    Node(int value) {
        data = value;
        next = nullptr;
    }
};

// Function to find pairs in the doubly linked list
// whose sum equals the given value x
vector<pair<int, int>> findPairsWithGivenSum(Node *head, int target) {
    vector<pair<int, int>> ans;
    unordered_map<int, Node *> visited;
    Node *currNode = head;

    // Traverse the doubly linked list
    while (currNode != nullptr) {

        int x = target - currNode->data;

        // Check if the target exists in the map
        if (visited.find(x) != visited.end()) {

            // Pair found
            ans.push_back({x, currNode->data});
        }

        // Store the current node's value in the map
        visited[currNode->data] = currNode;
        currNode = currNode->next;
    }

    sort(ans.begin(), ans.end());

    return ans;
}

int main() {

    // Create a doubly linked list: 1 <-> 2 <-> 4 <-> 5
    Node *head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(4);
    head->next->next->next = new Node(5);

    int target = 7;
    vector<pair<int, int>> pairs = findPairsWithGivenSum(head, target);

    if (pairs.empty()) {
        cout << "No pairs found." << endl;
    }
    else {
        for (auto &pair : pairs) {
            cout << pair.first << " " << pair.second << endl;
        }
    }

    return 0;
}


